// ── Auth check ──
const auth = $('Auth Lookup').item.json;
if (!auth.home_scope || auth.home_scope === '__UNAUTHORIZED__') {
  return [{ json: { error: 'Unauthorized: invalid API key', statusCode: 401, success: false } }];
}
const homeScope = auth.home_scope;
const allowedScopes = Array.isArray(auth.allowed_scopes) ? auth.allowed_scopes : [];
const readScopes = [homeScope, ...allowedScopes];

const body = $('Extract Key').item.json.body;

const action = body.action;
const id = body.id || null;
const data = body.data || {};

function esc(val) {
  if (val === null || val === undefined) return 'NULL';
  return "'" + String(val).replace(/'/g, "''") + "'";
}

function escArray(arr) {
  if (!Array.isArray(arr) || arr.length === 0) return "'{}'";
  const inner = arr.map(t => '"' + String(t).replace(/"/g, '\\"').replace(/'/g, "''") + '"').join(',');
  return "'{" + inner + "}'";
}

function escJson(obj) {
  if (!obj || typeof obj !== 'object') return "'{}'::jsonb";
  const jsonStr = JSON.stringify(obj).replace(/'/g, "''");
  return "'" + jsonStr + "'::jsonb";
}

function scopeFilter() {
  return `scope IN (${readScopes.map(s => esc(s)).join(', ')})`;
}

const validActions = ['list-categories', 'get', 'update', 'delete', 'stats', 'list-meta', 'guard-list', 'guard-stats', 'guard-resolve'];
if (!action || !validActions.includes(action)) {
  return [{ json: { error: 'action is required and must be one of: ' + validActions.join(', '), statusCode: 400, success: false } }];
}

let query;

switch (action) {
  case 'list-categories':
    query = `SELECT category, count(*)::int AS count FROM context_blocks WHERE ${scopeFilter()} GROUP BY category ORDER BY count DESC`;
    break;

  case 'get':
    if (!id) {
      return [{ json: { error: 'id is required for get action', statusCode: 400, success: false } }];
    }
    const apiKey = $('Extract Key').item.json.apiKey;
    query = `WITH access_log AS (
      INSERT INTO context_access_log (block_id, api_key_id, action)
      VALUES (${esc(id)}::uuid, (SELECT id FROM context_api_keys WHERE key_hash = encode(digest(${esc(apiKey)}, 'sha256'), 'hex') LIMIT 1), 'manage-get')
      ON CONFLICT DO NOTHING
      RETURNING id
    )
    SELECT id, category, tags, title, content, metadata, scope, created_at, updated_at FROM context_blocks WHERE id = ${esc(id)} AND ${scopeFilter()} LIMIT 1`;
    break;

  case 'update':
    if (!id) {
      return [{ json: { error: 'id is required for update action', statusCode: 400, success: false } }];
    }
    const setClauses = [];
    if (data.category !== undefined) setClauses.push(`category = ${esc(data.category)}`);
    if (data.title !== undefined) setClauses.push(`title = ${esc(data.title)}`);
    if (data.content !== undefined) setClauses.push(`content = ${esc(data.content)}`);
    if (data.tags !== undefined) setClauses.push(`tags = ${escArray(data.tags)}`);
    if (data.metadata !== undefined) setClauses.push(`metadata = ${escJson(data.metadata)}`);
    if (data.scope !== undefined) {
      if (data.scope === homeScope || (data.scope === 'shared' && allowedScopes.includes('shared'))) {
        setClauses.push(`scope = ${esc(data.scope)}`);
      } else {
        return [{ json: { error: 'Cannot set scope to: ' + data.scope, statusCode: 403, success: false } }];
      }
    }
    setClauses.push('updated_at = now()');

    if (setClauses.length <= 1) {
      return [{ json: { error: 'data must contain at least one field to update', statusCode: 400, success: false } }];
    }
    query = `UPDATE context_blocks SET ${setClauses.join(', ')} WHERE id = ${esc(id)} AND scope = ${esc(homeScope)} RETURNING id, category, tags, title, content, metadata, scope, created_at, updated_at`;
    break;

  case 'delete':
    if (!id) {
      return [{ json: { error: 'id is required for delete action', statusCode: 400, success: false } }];
    }
    query = `DELETE FROM context_blocks WHERE id = ${esc(id)} AND scope = ${esc(homeScope)} RETURNING id, category, title, scope`;
    break;

  case 'stats':
    query = `SELECT
      (SELECT count(*)::int FROM context_blocks WHERE ${scopeFilter()}) AS total_blocks,
      (SELECT count(DISTINCT category)::int FROM context_blocks WHERE ${scopeFilter()}) AS total_categories,
      (SELECT min(created_at) FROM context_blocks WHERE ${scopeFilter()}) AS oldest_entry,
      (SELECT max(created_at) FROM context_blocks WHERE ${scopeFilter()}) AS newest_entry,
      (SELECT pg_size_pretty(pg_total_relation_size('context_blocks'))) AS db_size`;
    break;

  case 'list-meta':
    query = `SELECT id, title, category, tags, scope, updated_at FROM context_blocks WHERE ${scopeFilter()} ORDER BY category, title`;
    break;

  case 'guard-list': {
    const category = body.category || null;
    const status = data.status || null;
    const limit = Math.min(Math.max(parseInt(body.limit) || 50, 1), 200);
    const scopeList = readScopes.map(s => esc(s)).join(', ');
    const categoryFilter = category
      ? `AND b.category = ${esc(category)}`
      : '';
    const statusFilter = status
      ? `AND b.guard_status = ${esc(status)}`
      : `AND b.guard_status NOT IN ('active', 'clean')`;

    query = `SELECT b.id, b.title, b.category, b.scope, b.guard_status,
       b.metadata->>'guard_similarity' AS similarity,
       CASE
         WHEN mb.id IS NULL THEN NULL
         WHEN mb.scope IN (${scopeList}) THEN b.metadata->>'guard_matched_id'
         ELSE NULL
       END AS matched_id,
       CASE
         WHEN mb.id IS NULL THEN NULL
         WHEN mb.scope IN (${scopeList}) THEN mb.title
         ELSE '[redacted]'
       END AS matched_title,
       b.metadata->>'guard_checked_at' AS checked_at,
       b.updated_at
FROM context_blocks b
LEFT JOIN context_blocks mb ON mb.id::text = b.metadata->>'guard_matched_id'
WHERE NOT b.is_archived
  AND b.scope IN (${scopeList})
  ${statusFilter}
  ${categoryFilter}
ORDER BY (b.metadata->>'guard_similarity')::numeric DESC NULLS LAST
LIMIT ${limit}`;
    break;
  }

  case 'guard-stats': {
    const sf = scopeFilter();
    query = `SELECT
  (SELECT count(*)::int FROM context_blocks WHERE NOT is_archived AND ${sf}) AS total_blocks,
  (SELECT count(*)::int FROM context_blocks WHERE NOT is_archived AND ${sf} AND guard_status = 'active') AS active,
  (SELECT count(*)::int FROM context_blocks WHERE NOT is_archived AND ${sf} AND guard_status = 'clean') AS clean,
  (SELECT count(*)::int FROM context_blocks WHERE NOT is_archived AND ${sf} AND guard_status = 'needs_review') AS needs_review,
  (SELECT count(*)::int FROM context_blocks WHERE NOT is_archived AND ${sf} AND guard_status = 'near_duplicate') AS near_duplicate,
  (SELECT count(*)::int FROM context_blocks WHERE NOT is_archived AND ${sf} AND (metadata->>'guard_checked_at') IS NULL) AS unchecked,
  (SELECT count(*)::int FROM context_blocks WHERE is_archived AND ${sf} AND guard_status = 'archived_dup') AS archived_dups,
  (SELECT dirty_since FROM context_guard_state LIMIT 1) AS dirty_since,
  (SELECT last_guard_at FROM context_guard_state LIMIT 1) AS last_guard_at,
  (SELECT pending_count::int FROM context_guard_state LIMIT 1) AS pending_count,
  (SELECT count(*)::int FROM context_write_log wl JOIN context_blocks cb ON wl.block_id = cb.id WHERE cb.${sf}) AS write_log_entries`;
    break;
  }

  case 'guard-resolve': {
    if (!id) {
      return [{ json: { error: 'id is required for guard-resolve action', statusCode: 400, success: false } }];
    }

    const resolution = data.resolution;
    if (!resolution || !['archive', 'keep'].includes(resolution)) {
      return [{ json: { error: "data.resolution is required and must be 'archive' or 'keep'", statusCode: 400, success: false } }];
    }

    if (resolution === 'archive') {
      query = `UPDATE context_blocks SET
        is_archived = true,
        guard_status = 'archived_dup',
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'guard_resolved_at', now()::text,
          'guard_resolution', 'archive'
        ),
        updated_at = now()
      WHERE id = ${esc(id)}
        AND scope = ${esc(homeScope)}
        AND NOT is_archived
      RETURNING id, title, category, scope, guard_status`;
    } else {
      query = `UPDATE context_blocks SET
        guard_status = 'active',
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'guard_resolved_at', now()::text,
          'guard_resolution', 'keep'
        ),
        updated_at = now()
      WHERE id = ${esc(id)}
        AND scope = ${esc(homeScope)}
      RETURNING id, title, category, scope, guard_status`;
    }
    break;
  }
}

