    break;
  case 'guard-stats': {
    const s = rows[0] || {};
    response.total_blocks     = s.total_blocks     ?? 0;
    response.active           = s.active           ?? 0;
    response.clean            = s.clean            ?? 0;
    response.needs_review     = s.needs_review     ?? 0;
    response.near_duplicate   = s.near_duplicate   ?? 0;
    response.unchecked        = s.unchecked        ?? 0;
    response.archived_dups    = s.archived_dups    ?? 0;
    response.write_log_entries = s.write_log_entries ?? 0;
    response.dirty_since      = s.dirty_since      ?? null;
    response.last_guard_at    = s.last_guard_at    ?? null;
    response.pending_count    = s.pending_count    ?? 0;
    break;
  }
  case 'guard-resolve':
    if (rows.length === 0) {
      response = { success: false, error: 'Block not found or not in your scope', action: action };
    } else {
      const row = rows[0];
      response.resolved = {
        id: row.id,
        title: row.title,
        category: row.category,
        scope: row.scope,
        resolution: row.guard_status === 'archived_dup' ? 'archive' : 'keep',
        guard_status: row.guard_status
      };
    }
    break;
}

return [{ json: response }];

